    auto n = static_cast<uint32_t>(x_shape->GetDim(0));
    auto cin = static_cast<uint32_t>(x_shape->GetDim(1));
    auto hin = static_cast<uint32_t>(x_shape->GetDim(2));
    auto win = static_cast<uint32_t>(x_shape->GetDim(3));

    auto cout = static_cast<uint32_t>(w_shape->GetDim(0));
    auto kH = static_cast<uint32_t>(w_shape->GetDim(2));
    auto kW = static_cast<uint32_t>(w_shape->GetDim(3));

    // Attributes (defaults: stride=1, pad=0, dil=1)
    int64_t stride_h = GetAttrInt(context, "stride_h", 1);
    int64_t stride_w = GetAttrInt(context, "stride_w", 1);
    int64_t pad_h = GetAttrInt(context, "pad_h", 0);
    int64_t pad_w = GetAttrInt(context, "pad_w", 0);
    int64_t dil_h = GetAttrInt(context, "dil_h", 1);
    int64_t dil_w = GetAttrInt(context, "dil_w", 1);

    const int64_t effKH = (kH - 1) * dil_h + 1;
    const int64_t effKW = (kW - 1) * dil_w + 1;

