    tiling.set_N(n);
    tiling.set_Cin(cin);
    tiling.set_Hin(hin);
    tiling.set_Win(win);
    tiling.set_Cout(cout);
    tiling.set_kH(kH);
    tiling.set_kW(kW);
    tiling.set_padH(static_cast<uint32_t>(pad_h));
